'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';

interface Contest {
  _id: string;
  place: number;
  event: string;
  year: number;
  rating: number;
  ctfPoints: number;
  icon?: string;
}

export default function ContestsPage() {
  const [contests, setContests] = useState<Contest[]>([]);
  const [loading, setLoading] = useState(true);
  const [limit, setLimit] = useState(25);
  const [showAll, setShowAll] = useState(false);

  useEffect(() => {
    fetchContests();
  }, [limit]);

  const fetchContests = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/contests?limit=${limit}`);
      const data = await response.json();
      
      if (data.success) {
        setContests(data.data);
      }
    } catch (error) {
      console.error('Error fetching contests:', error);
    } finally {
      setLoading(false);
    }
  };

  const getPlaceIcon = (place: number) => {
    if (place === 1) return '👑';
    if (place === 2) return '🥈';
    if (place === 3) return '🥉';
    if (place === 4) return '🏅';
    return '🏆';
  };

  const toggleShowAll = () => {
    if (showAll) {
      setLimit(25);
    } else {
      setLimit(100);
    }
    setShowAll(!showAll);
  };

  return (
    <div className="min-h-screen pt-24 pb-16 px-4 sm:px-6">
      <div className="container mx-auto max-w-6xl">
        {/* Breadcrumb */}
        <div className="mb-6 text-sm text-gray-400">
          <Link href="/" className="hover:text-ccug-purple transition">
            Home
          </Link>
          <span className="mx-2">»</span>
          <span>Contests</span>
        </div>

        {/* Header */}
        <div className="mb-8 flex justify-between items-center flex-wrap gap-4">
          <h1 className="text-3xl sm:text-4xl font-bold">Contests</h1>
          
          <button
            onClick={toggleShowAll}
            className="px-6 py-2 bg-ccug-purple hover:bg-ccug-purple/80 rounded-lg transition font-semibold text-sm"
          >
            {showAll ? 'Show Top 25' : 'Show Top 100'}
          </button>
        </div>

        {/* Table */}
        {loading ? (
          <div className="text-center py-12">
            <div className="inline-block animate-spin rounded-full h-12 w-12 border-4 border-ccug-purple border-t-transparent"></div>
            <p className="mt-4 text-gray-400">Loading contests...</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full border-collapse">
              {/* Table Header */}
              <thead>
                <tr className="bg-ccug-purple/20 text-left">
                  <th className="px-4 sm:px-6 py-4 font-semibold text-sm sm:text-base rounded-tl-lg">
                    PLACE
                  </th>
                  <th className="px-4 sm:px-6 py-4 font-semibold text-sm sm:text-base">
                    EVENT
                  </th>
                  <th className="px-4 sm:px-6 py-4 font-semibold text-sm sm:text-base text-right rounded-tr-lg">
                    POINTS
                  </th>
                </tr>
              </thead>

              {/* Table Body */}
              <tbody>
                {contests.map((contest, index) => (
                  <tr
                    key={contest._id}
                    className={`border-b border-gray-800 hover:bg-gray-900/50 transition ${
                      index % 2 === 0 ? 'bg-gray-900/20' : ''
                    }`}
                  >
                    {/* Place */}
                    <td className="px-4 sm:px-6 py-4">
                      <div className="flex items-center gap-2 sm:gap-3">
                        <span className="text-xl sm:text-2xl">
                          {getPlaceIcon(contest.place)}
                        </span>
                        <span className="font-bold text-lg sm:text-xl">
                          {contest.place}
                        </span>
                      </div>
                    </td>

                    {/* Event */}
                    <td className="px-4 sm:px-6 py-4">
                      <div>
                        <p className="font-semibold text-sm sm:text-base">
                          {contest.event}
                        </p>
                        <p className="text-xs sm:text-sm text-gray-400">
                          ({contest.year})
                        </p>
                      </div>
                    </td>

                    {/* Points */}
                    <td className="px-4 sm:px-6 py-4 text-right">
                      <div>
                        <p className="text-ccug-purple font-bold text-sm sm:text-base">
                          {contest.rating.toFixed(3)} rating points
                        </p>
                        <p className="text-xs sm:text-sm text-blue-400">
                          {contest.ctfPoints.toLocaleString()} CTF points
                        </p>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            {contests.length === 0 && (
              <div className="text-center py-12 text-gray-400">
                <p className="text-lg">No contests found</p>
              </div>
            )}
          </div>
        )}

        {/* Stats Summary */}
        {contests.length > 0 && (
          <div className="mt-8 p-6 bg-gray-900/50 rounded-lg border border-ccug-purple/20">
            <h3 className="text-xl font-bold mb-4">Achievement Summary</h3>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div>
                <p className="text-gray-400 text-sm">Total Contests</p>
                <p className="text-2xl font-bold text-ccug-purple">{contests.length}</p>
              </div>
              <div>
                <p className="text-gray-400 text-sm">Best Placement</p>
                <p className="text-2xl font-bold text-ccug-purple">
                  #{Math.min(...contests.map(c => c.place))}
                </p>
              </div>
              <div>
                <p className="text-gray-400 text-sm">Total Points</p>
                <p className="text-2xl font-bold text-ccug-purple">
                  {contests.reduce((sum, c) => sum + c.ctfPoints, 0).toLocaleString()}
                </p>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}